import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"API 约定","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api.md","filePath":"guide/api.md","lastUpdated":1787901540000}'),r={name:"guide/api.md"};function c(i,e,s,p,h,n){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="api-约定" tabindex="-1">API 约定 <a class="header-anchor" href="#api-约定" aria-label="Permalink to &quot;API 约定&quot;">​</a></h1><h2 id="地址与响应" tabindex="-1">地址与响应 <a class="header-anchor" href="#地址与响应" aria-label="Permalink to &quot;地址与响应&quot;">​</a></h2><p>核心 API 前缀由 <code>settings.API_PREFIX</code> 配置，默认是 <code>/api/v1</code>。Apehub_web API 在此基础上使用 <code>/apehub-web</code> 前缀。</p><p>成功响应格式为 <code>{ code, msg, data }</code>。业务错误使用 <code>401</code>（登录态无效）、<code>403</code>（权限不足）、<code>404</code>（资源不存在）、<code>409</code>（状态冲突）和 <code>422</code>（参数校验失败）。</p><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><p>需要登录的请求携带：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;access_token&gt;</span></span></code></pre></div><p>核心依赖 <code>get_current_user</code> 校验 JWT、用户状态和用户记录。后台权限接口还需要 <code>require_permission(&quot;system:user:list&quot;)</code> 这类权限依赖；插件接口应使用自己的 <code>apehub_web:*</code> 权限标识。</p><h2 id="核心接口分组" tabindex="-1">核心接口分组 <a class="header-anchor" href="#核心接口分组" aria-label="Permalink to &quot;核心接口分组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>作用</th></tr></thead><tbody><tr><td><code>/auth</code></td><td>登录、刷新令牌、当前用户信息</td></tr><tr><td><code>/users</code></td><td>用户管理</td></tr><tr><td><code>/roles</code></td><td>角色和菜单权限</td></tr><tr><td><code>/menus</code></td><td>菜单树和动态路由来源</td></tr><tr><td><code>/depts</code></td><td>部门和数据范围</td></tr><tr><td><code>/plugins</code></td><td>插件发现、热启停、上传和卸载</td></tr><tr><td><code>/mcp</code></td><td>工具、资源、提示词和审计</td></tr><tr><td><code>/apehub-web/site/public</code></td><td>官网公开数据</td></tr><tr><td><code>/apehub-web/developer</code></td><td>插件开发者工作台</td></tr><tr><td><code>/apehub-web/admin</code></td><td>官网和市场后台管理</td></tr></tbody></table><h2 id="编写插件-api" tabindex="-1">编写插件 API <a class="header-anchor" href="#编写插件-api" aria-label="Permalink to &quot;编写插件 API&quot;">​</a></h2><p>插件路由应在插件自己的 <code>register()</code> 中挂载，使用 Pydantic 请求模型和统一异常类型。不要在公开接口返回密钥、内部文件路径或未发布版本数据；文件路径必须经过目录边界校验。</p>',12)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
